        return FailureStatus(bookResult.ErrorMessage);
    }
    db.Books.Add(bookResult.Value);
    await db.SaveChangesAsync();
    return Results.Created(string.Concat("/api/books/", bookResult.Value.ISBN), bookResult.Value);
});

